/** Candidate options for a future scaffolding CLI. No files or runtime services
 * are generated by this read-only planner. Keep mappings reviewable and explicit.
 */
export const UI_PRESETS = Object.freeze(['quasar2', 'daisyui', 'daisyui-kit'])
export const SCHEMA_PRESETS = Object.freeze(['typebox', 'json', 'zod'])
export const AUTH_PRESETS = Object.freeze(['none', 'jwt', 'local', 'oauth', 'oidc', 'ldap'])
export const DATABASE_PRESETS = Object.freeze(['memory', 'mongodb', 'postgresql', 'mariadb', 'mysql', 'sqlite'])
export const RENDER_PRESETS = Object.freeze(['spa', 'ssr', 'ssg'])
export const RENDER_ENGINES = Object.freeze(['auto', 'vite', 'quasar-cli-vite'])
export const TRANSPORT_PRESETS = Object.freeze(['rest', 'socketio', 'both'])
export const NAME_PATTERN = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/

const AVAILABLE_OPTIONS = new Set(['--name', '--ui', '--render', '--pwa', '--schema', '--auth', '--db', '--primary', '--transport', '--engine', '--dry-run', '--json', '--help'])

function requiredChoice(value, choices, name) {
  if (!choices.includes(value)) throw new Error(`Invalid ${name}: expected ${choices.join('|')}`)
  return value
}
function parseUniqueCsv(value, name) {
  if (typeof value !== 'string' || !value || value.length > 512) throw new Error(`Invalid ${name}`)
  const parts = value.split(',')
  if (!parts.length || parts.some(part => !part || part !== part.trim()) || new Set(parts).size !== parts.length) throw new Error(`Invalid or duplicate ${name}`)
  return parts
}
export function parsePlanArguments(args) {
  if (args.includes('--help') || args.includes('-h')) return { help: true }
  const options = { name: 'my-feathers-app', ui: 'daisyui', render: 'spa', pwa: 'off', schema: 'typebox', auth: 'none', db: 'main:memory', primary: 'main', transport: 'rest', engine: 'auto', dryRun: true, json: false }
  const seen = new Set()
  for (let index = 0; index < args.length; index++) {
    const flag = args[index]
    if (!AVAILABLE_OPTIONS.has(flag) || flag === '--help' || seen.has(flag)) throw new Error(`Unknown or duplicate option: ${flag}`)
    seen.add(flag)
    if (flag === '--dry-run' || flag === '--json') options[flag === '--dry-run' ? 'dryRun' : 'json'] = true
    else {
      const value = args[++index]
      if (!value || value.startsWith('--')) throw new Error(`Missing value for ${flag}`)
      options[flag.slice(2)] = value
    }
  }
  return options
}
export function normalizePlanOptions(input) {
  const name = input.name ?? 'my-feathers-app'
  if (typeof name !== 'string' || name.length > 48 || !NAME_PATTERN.test(name)) throw new Error('Invalid --name: lowercase kebab-case, maximum 48 characters')
  const ui = requiredChoice(input.ui ?? 'daisyui', UI_PRESETS, '--ui')
  const render = requiredChoice(input.render ?? 'spa', RENDER_PRESETS, '--render')
  const pwa = requiredChoice(input.pwa ?? 'off', ['on', 'off'], '--pwa')
  const schema = requiredChoice(input.schema ?? 'typebox', SCHEMA_PRESETS, '--schema')
  const transport = requiredChoice(input.transport ?? 'rest', TRANSPORT_PRESETS, '--transport')
  const requestedEngine = requiredChoice(input.engine ?? 'auto', RENDER_ENGINES, '--engine')
  // Quasar Vite plugin works in SPA; Quasar CLI with Vite is a separate toolchain
  // required for SSR/SSG. Neither integrates this Feathers plugin automatically.
  const engine = requestedEngine === 'auto'
    ? (ui === 'quasar2' && render !== 'spa' ? 'quasar-cli-vite' : 'vite')
    : requestedEngine
  if (ui !== 'quasar2' && engine === 'quasar-cli-vite') throw new Error('Quasar CLI is only compatible with --ui quasar2')
  if (ui === 'quasar2' && render !== 'spa' && engine === 'vite') throw new Error('Quasar standalone Vite plugin supports SPA only; select --engine quasar-cli-vite for SSR/SSG')
  const auth = parseUniqueCsv(input.auth ?? 'none', '--auth')
  for (const strategy of auth) requiredChoice(strategy, AUTH_PRESETS, '--auth')
  if (auth.includes('none') && auth.length > 1) throw new Error('Cannot combine --auth none with authentication strategies')
  // AuthenticationService issues JWTs for the standard local and OAuth flows.
  if (auth.some(strategy => ['local', 'oauth'].includes(strategy)) && !auth.includes('jwt')) auth.unshift('jwt')
  const databases = parseUniqueCsv(input.db ?? 'main:memory', '--db').map(spec => {
    const match = /^([a-z][a-z0-9-]{0,31}):([a-z]+)$/.exec(spec)
    if (!match) throw new Error('Invalid --db: use alias:adapter[,alias:adapter]')
    const [, alias, adapter] = match
    requiredChoice(adapter, DATABASE_PRESETS, '--db adapter')
    return { alias, adapter }
  })
  if (new Set(databases.map(db => db.alias)).size !== databases.length) throw new Error('Duplicate database connection alias')
  const primary = input.primary ?? 'main'
  if (!databases.some(db => db.alias === primary)) throw new Error('--primary must match a --db alias')
  return { name, ui, render, engine, pwa, schema, transport, auth, databases, primary, dryRun: true, json: Boolean(input.json) }
}
